const input = $json.body ?? $json;
const email = String(input.email || '').trim().toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error('A valid email is required');
}
const domain = String(input.website || '').toLowerCase()
  .replace(/^https?:\/\//, '').split('/')[0].replace(/^www\./, '');
const fixtures = {
  'abc-retail.example': { company_name: 'ABC Retail', industry: 'Retail', employees: 80, country: 'Vietnam', signals: ['Hiring operations staff'] },
  'northstar.example': { company_name: 'Northstar', industry: 'SaaS', employees: 120, country: 'Singapore', signals: ['Expanded product team'] },
  'mekong-distribution.example': { company_name: 'Mekong Distribution', industry: 'Distribution', employees: 240, country: 'Vietnam', signals: ['Opened a new distribution center'] }
};
// Mock waterfall: provider A exact domain, then provider B fixture fallback.
// Replace this block with Clay table/API integration in V2.
let enrichment_source = 'submitted_data';
let enriched = {};
if (fixtures[domain]) {
  enriched = fixtures[domain];
  enrichment_source = 'mock_provider_a';
} else {
  const fallback = Object.entries(fixtures).find(([d]) => domain.endsWith('.example') && d === 'abc-retail.example');
  if (fallback) {
    enriched = fallback[1];
    enrichment_source = 'mock_provider_b';
  }
}
const lead = { ...input, ...Object.fromEntries(Object.entries(enriched).filter(([k,v]) => !input[k] || k === 'signals')) };
lead.email = email;
lead.company_name = lead.company_name || input.company_name || '';
lead.website = input.website || '';
lead.industry = lead.industry || input.industry || 'Unknown';
lead.country = lead.country || input.country || 'Unknown';
lead.employees = Number(lead.employees ?? input.employees ?? 0);
lead.enrichment_status = Object.keys(enriched).length ? 'enriched_mock' : 'partial';
lead.enrichment_source = enrichment_source;
lead.signals = lead.signals || [];
let score = 0;
const reasons = [];
if (['software','saas','technology','retail','distribution'].includes(String(lead.industry).toLowerCase())) { score += 20; reasons.push('Target industry +20'); }
if (lead.employees >= 20 && lead.employees <= 500) { score += 20; reasons.push('Company size 20-500 +20'); }
if (['vietnam','singapore','malaysia','united states','usa'].includes(String(lead.country).toLowerCase())) { score += 15; reasons.push('Target geography +15'); }
if (/(founder|ceo|director|manager|head|vp)/i.test(lead.job_title || '')) { score += 20; reasons.push('Decision-maker title +20'); }
if (/(automation|crm|inventory|analytics|data|sales|marketing)/i.test(lead.business_need || '')) { score += 25; reasons.push('Relevant business need +25'); }
const band = score >= 75 ? 'HOT' : score >= 50 ? 'WARM' : 'COLD';
const owner = score >= 75 ? 'Senior Sales' : score >= 50 ? 'Sales Development' : 'Marketing Nurture';
const status = score >= 50 ? 'needs_human_review' : 'nurture';
const now = new Date().toISOString();
return { json: {
  email, first_name: input.first_name || '', last_name: input.last_name || '',
  company_name: lead.company_name, website: lead.website,
  industry: lead.industry, employees: lead.employees,
  country: lead.country, job_title: input.job_title || '',
  business_need: input.business_need || '', source: input.source || 'website',
  enrichment_status: lead.enrichment_status, enrichment_source: lead.enrichment_source,
  signals: lead.signals, score, score_band: band, score_reasons: reasons,
  owner, status, ai_mode: 'not_configured_rules_only',
  ai_qualification: { fit: band.toLowerCase(), summary: 'V1 uses deterministic ICP rules; AI connector is reserved for V2.', recommended_action: 'Human review before outbound' },
  human_approval_required: score >= 50, updated_at: now,
  event_type: 'lead_processed', event_detail: `score=${score}; band=${band}; owner=${owner}; enrichment=${enrichment_source}`
} };
